using System.Collections.Generic;

namespace KCppAssist
{
    /// <summary>設定の画面の説明文の翻訳(日本語 → 英語・中国語(簡体字)・韓国語)。鍵は OptionsPage.cs の LocDescription の文字そのまま。</summary>
    internal static class LangDescriptions
    {
        public static readonly Dictionary<string, string[]> Rows = new Dictionary<string, string[]>(System.StringComparer.Ordinal)
        {
            ["メニュー・電球・ダイアログ・この設定の画面の言語。初期値は日本語で、初めて起動したときだけ、PC の表示言語に合わせます(日本語・中国語・韓国語以外は English)。設定の画面の文字は、Visual Studio を開き直すと変わります。"] = new[] { "Language of menus, light bulbs, dialogs and this settings page. The default is Japanese; only on the first run it follows the PC display language (English unless Japanese, Chinese or Korean). This settings page changes after Visual Studio is restarted.", "菜单、灯泡、对话框以及此设置页面的语言。默认是日本语，仅在首次启动时跟随电脑的显示语言（日语、中文、韩语以外为 English）。此设置页面的文字在重新打开 Visual Studio 后才会改变。", "메뉴·전구·대화 상자·이 설정 화면의 언어. 기본값은 일본어이며, 처음 실행할 때만 PC의 표시 언어에 맞춥니다(일본어·중국어·한국어 외에는 English). 설정 화면의 글자는 Visual Studio를 다시 열면 바뀝니다." },
            ["True のとき、Alt+G で作る Getter と Setter の間と、その前の行との間と、足した行の下(すぐ次が別のメンバーや private: のとき)に、空行を 1 行入れます。"] = new[] { "When True, inserts one blank line between the Getter and Setter made with Alt+G, before them, and after them (when the next line is another member or private:).", "为 True 时，在用 Alt+G 生成的 Getter 与 Setter 之间、其前一行之间、以及新增行之后（下一行是其他成员或 private: 时）各插入一个空行。", "True이면 Alt+G로 만든 Getter와 Setter 사이, 그 앞 줄과의 사이, 추가한 줄 아래(바로 다음이 다른 멤버나 private:일 때)에 빈 줄을 1줄 넣습니다." },
            ["Off: 何もしない。ManualOnly: Alt+I (Include) を押したときだけ足す。Auto: Alt+I に加えて、入力中に未定義の型を見つけると、自動で足す。"] = new[] { "Off: do nothing. ManualOnly: add only when Alt+I (Include) is pressed. Auto: in addition to Alt+I, add automatically when an undefined type is found while typing.", "Off：不做任何事。ManualOnly：仅在按 Alt+I (Include) 时添加。Auto：除 Alt+I 外，输入时发现未定义的类型会自动添加。", "Off: 아무것도 안 함. ManualOnly: Alt+I (Include)를 눌렀을 때만 추가. Auto: Alt+I에 더해 입력 중 정의되지 않은 형식을 찾으면 자동으로 추가." },
            ["識別子を打ち終えてから、この時間だけ入力が止まったら調べます。"] = new[] { "Checks after typing of an identifier has stopped for this long.", "标识符输入完成后，停止输入达到此时长才检查。", "식별자를 다 입력한 뒤 이 시간만큼 입력이 멈추면 검사합니다." },
            ["カンマ区切り。ソリューションのヘッダーから引くときだけ、この名前の型は自動で足しません(Alt+I では足せます)。標準ライブラリの名前には効きません。"] = new[] { "Comma-separated. Types with these names are not added automatically when looked up from solution headers (Alt+I can still add them). Has no effect on standard library names.", "逗号分隔。从解决方案头文件查找时，这些名称的类型不会自动添加（Alt+I 仍可添加）。对标准库名称无效。", "쉼표로 구분. 솔루션 헤더에서 찾을 때 이 이름의 형식은 자동으로 추가하지 않습니다(Alt+I로는 추가 가능). 표준 라이브러리 이름에는 적용되지 않습니다." },
            ["カンマ区切りのフォルダー名。この名前のフォルダーの下は、型の索引に入れません。"] = new[] { "Comma-separated folder names. Folders with these names are not added to the type index.", "逗号分隔的文件夹名。这些名称的文件夹不会加入类型索引。", "쉼표로 구분한 폴더 이름. 이 이름의 폴더 아래는 형식 색인에 넣지 않습니다." },
            ["Off: 何もしない。ManualOnly: Alt+S を押したときだけ合わせる。Auto: Alt+S に加えて、ヘッダーの宣言か cpp の定義の引数を変えると、相手の引数を自動で書き換える(相手が開いていなければ開く)。"] = new[] { "Off: do nothing. ManualOnly: sync only when Alt+S is pressed. Auto: in addition to Alt+S, when you change the parameters of a header declaration or cpp definition, the counterpart's parameters are rewritten automatically (opened if needed).", "Off：不做任何事。ManualOnly：仅在按 Alt+S 时同步。Auto：除 Alt+S 外，修改头文件声明或 cpp 定义的参数时，自动改写对方的参数（未打开则打开）。", "Off: 아무것도 안 함. ManualOnly: Alt+S를 눌렀을 때만 맞춤. Auto: Alt+S에 더해 헤더 선언이나 cpp 정의의 매개변수를 바꾸면 상대의 매개변수를 자동으로 고칩니다(열려 있지 않으면 엶)." },
            ["最後に入力してから、相手の引数を書き換えるまでの待ち。0 なら、打つそばから(次の入力の処理が終わり次第)相手が変わります。初期値は 0。"] = new[] { "Delay from the last keystroke until the counterpart's parameters are rewritten. With 0, the counterpart changes as you type (as soon as the next input is processed). Default 0.", "从最后一次输入到改写对方参数的等待时间。为 0 时随输入即改（下一次输入处理完即变）。默认 0。", "마지막 입력부터 상대 매개변수를 고칠 때까지의 대기. 0이면 입력하는 대로(다음 입력 처리가 끝나는 즉시) 바뀝니다. 기본값 0." },
            ["True のとき、引数を相手のファイルへ写したときや、名前を変えたときに、変えた内容を約 3 秒だけ見せます。ウィンドウは、変えた名前の 1 文字目に左端をそろえて、その行のすぐ上に出ます(名前には重なりません)。"] = new[] { "When True, shows what was changed for about 3 seconds when parameters are copied to the counterpart or a name is renamed. The window is aligned to the first character of the changed name, just above that line (it never covers the name).", "为 True 时，将参数复制到对方或重命名时，约显示 3 秒修改内容。窗口左端对齐修改名称的第一个字符，出现在该行正上方（不会遮住名称）。", "True이면 매개변수를 상대 파일로 옮기거나 이름을 바꿀 때 바뀐 내용을 약 3초 보여 줍니다. 창은 바뀐 이름의 첫 글자에 왼쪽을 맞춰 그 줄 바로 위에 나옵니다(이름을 가리지 않음)." },
            ["Off: 何もしない。OnLeave: カーソルが名前から離れたときに、まとめて変える。Auto: 打つそばから変える。対象は、ローカル変数・引数・メンバー変数・メンバー関数・関数の、宣言(と定義)の名前。使っている側の名前を書き換えても、ほかは変えません。"] = new[] { "Off: do nothing. OnLeave: rename all at once when the cursor leaves the name. Auto: rename as you type. Applies to the declared (and defined) names of local variables, parameters, member variables, member functions and functions. Editing a name at a use site does not change the others.", "Off：不做任何事。OnLeave：光标离开名称时一并修改。Auto：随输入修改。对象为局部变量、参数、成员变量、成员函数、函数的声明（及定义）名称。修改使用处的名称不会影响其他位置。", "Off: 아무것도 안 함. OnLeave: 커서가 이름에서 벗어날 때 한꺼번에 바꿈. Auto: 입력하는 대로 바꿈. 대상은 지역 변수·매개변수·멤버 변수·멤버 함수·함수의 선언(과 정의) 이름. 사용하는 쪽 이름을 고쳐도 다른 곳은 바꾸지 않습니다." },
            ["False(既定): obj.name や p->name のうち、obj の型を宣言から読めて、同じクラスだと分かるものだけ変える。分からないものは変えずに、出力ウィンドウの K-Cpp に一覧を出す。True: 分からないものも、同じ名前なら変える(別のクラスの同じ名前のメンバーも変わることがあります)。"] = new[] { "False (default): among obj.name and p->name, change only those whose obj type can be read from its declaration and is the same class. Unknown ones are listed in the K-Cpp output window instead. True: also change unknown ones with the same name (members with the same name in other classes may change too).", "False（默认）：在 obj.name 与 p->name 中，只修改能从声明读出 obj 类型且为同一类的那些。无法判断的不修改，并在输出窗口的 K-Cpp 中列出。True：无法判断的同名者也修改（其他类的同名成员也可能被修改）。", "False(기본): obj.name이나 p->name 중 obj의 형식을 선언에서 읽을 수 있고 같은 클래스인 것만 바꿈. 모르는 것은 바꾸지 않고 출력 창의 K-Cpp에 목록을 냄. True: 모르는 것도 같은 이름이면 바꿈(다른 클래스의 같은 이름 멤버도 바뀔 수 있음)." },
            ["True(既定): 宣言の名前を書き換えている間、一緒に変わる場所を点線の枠で囲む(書き換えている宣言は実線)。名前の変更が終わると消える。色は ツール → オプション → 環境 → フォントおよび色 の「K-Cpp: 一緒に変わる場所」で変えられます。"] = new[] { "True (default): while renaming a declaration, places that change with it are outlined with a dotted frame (the declaration being edited uses a solid frame). It disappears when renaming ends. Colors can be changed under Tools → Options → Environment → Fonts and Colors, \"K-Cpp: 一緒に変わる場所\".", "True（默认）：重命名声明期间，用虚线框标出一同修改的位置（正在修改的声明用实线框）。重命名结束后消失。颜色可在 工具 → 选项 → 环境 → 字体和颜色 的“K-Cpp: 一緒に変わる場所”中修改。", "True(기본): 선언 이름을 고치는 동안 함께 바뀌는 곳을 점선 테두리로 표시(고치고 있는 선언은 실선). 이름 변경이 끝나면 사라집니다. 색은 도구 → 옵션 → 환경 → 글꼴 및 색의 \"K-Cpp: 一緒に変わる場所\"에서 바꿀 수 있습니다." },
            ["True のとき、関数の引数を並べ替えるか消して、カーソルが括弧の外へ出ると、その関数の呼び出しの引数も同じ並びに直します。足した引数に渡す値は決められないので、その呼び出しは直さずに、出力ウィンドウの K-Cpp に一覧を出します。"] = new[] { "When True, after you reorder or remove a function's parameters and the cursor leaves the parentheses, the call sites' arguments are reordered the same way. Calls that would need a value for an added parameter are not changed and are listed in the K-Cpp output window.", "为 True 时，重排或删除函数参数后光标离开括号，调用处的实参也按同样顺序调整。新增参数无法确定传入的值，因此这些调用不修改，并在输出窗口的 K-Cpp 中列出。", "True이면 함수의 매개변수를 정렬하거나 지운 뒤 커서가 괄호 밖으로 나가면 그 함수 호출의 인수도 같은 순서로 고칩니다. 추가한 매개변수에 넘길 값은 정할 수 없으므로 그 호출은 고치지 않고 출력 창의 K-Cpp에 목록을 냅니다." },
            ["Off: 何もしない。ManualOnly: Alt+N でまとめて変えたときだけ、相手・#include・CMake を直す。Auto: 名前を変えたことを自動で見つけて(Solution Explorer、フォルダー ビュー、エクスプローラー)、直す。Alt+N も使えます。"] = new[] { "Off: do nothing. ManualOnly: update the paired file, #include and CMake only when renaming with Alt+N. Auto: detect renames automatically (Solution Explorer, Folder View, Explorer) and update them. Alt+N also works.", "Off：不做任何事。ManualOnly：仅在用 Alt+N 一起重命名时更新对应文件、#include 与 CMake。Auto：自动检测重命名（解决方案资源管理器、文件夹视图、资源管理器）并更新。也可使用 Alt+N。", "Off: 아무것도 안 함. ManualOnly: Alt+N으로 함께 바꿀 때만 짝 파일·#include·CMake를 고침. Auto: 이름이 바뀐 것을 자동으로 찾아(솔루션 탐색기, 폴더 보기, 탐색기) 고칩니다. Alt+N도 쓸 수 있습니다." },
            ["True のとき、Foo.h の名前を Bar.h に変えると、同じフォルダーの Foo.cpp も Bar.cpp にします(逆も同じ)。"] = new[] { "When True, renaming Foo.h to Bar.h also renames Foo.cpp in the same folder to Bar.cpp (and vice versa).", "为 True 时，把 Foo.h 改名为 Bar.h 时，同一文件夹的 Foo.cpp 也改为 Bar.cpp（反之亦然）。", "True이면 Foo.h를 Bar.h로 바꿀 때 같은 폴더의 Foo.cpp도 Bar.cpp로 바꿉니다(반대도 같음)." },
            ["True のとき、CMakeLists.txt と .cmake の中の、古いファイル名(src/Foo.cpp など)も、新しい名前に直します。"] = new[] { "When True, old file names (such as src/Foo.cpp) in CMakeLists.txt and .cmake files are also changed to the new name.", "为 True 时，CMakeLists.txt 与 .cmake 中的旧文件名（如 src/Foo.cpp）也改为新名称。", "True이면 CMakeLists.txt와 .cmake 안의 옛 파일 이름(src/Foo.cpp 등)도 새 이름으로 고칩니다." },
            ["True のとき、std::make_unique<T>(…)、std::make_shared<T>(…)、new T(…) の引数の個数が、T のどのコンストラクターにも合わないと、ビルドの前に、エディターで波線を引きます。型の細かい違い(const・暗黙の変換)は見ません。コンストラクターを書いていないクラス、テンプレート、継承したコンストラクター、マクロのあるクラスは調べません。"] = new[] { "When True, if the argument count of std::make_unique<T>(…), std::make_shared<T>(…) or new T(…) matches no constructor of T, a squiggle is drawn in the editor before building. Fine type differences (const, implicit conversions) are not checked. Classes without user constructors, templates, inherited constructors and classes with macros are not checked.", "为 True 时，若 std::make_unique<T>(…)、std::make_shared<T>(…)、new T(…) 的实参个数与 T 的任何构造函数都不匹配，会在构建前于编辑器中画波浪线。不检查类型的细微差别（const、隐式转换）。不检查未写构造函数的类、模板、继承的构造函数以及含宏的类。", "True이면 std::make_unique<T>(…), std::make_shared<T>(…), new T(…)의 인수 개수가 T의 어느 생성자와도 맞지 않으면 빌드 전에 편집기에 물결선을 긋습니다. 형식의 세세한 차이(const·암시적 변환)는 보지 않습니다. 생성자를 쓰지 않은 클래스, 템플릿, 상속한 생성자, 매크로가 있는 클래스는 검사하지 않습니다." },
            ["Error: 赤い波線(エラー)。Warning: 緑の波線(警告)。どちらも、ビルドの結果には影響しません。"] = new[] { "Error: red squiggle (error). Warning: green squiggle (warning). Neither affects the build result.", "Error：红色波浪线（错误）。Warning：绿色波浪线（警告）。两者都不影响构建结果。", "Error: 빨간 물결선(오류). Warning: 초록 물결선(경고). 어느 쪽도 빌드 결과에는 영향이 없습니다." },
            ["最後に入力してから、この時間だけ待って調べます。短くすると、すぐに波線が出ます。"] = new[] { "Waits this long after the last keystroke before checking. Shorter values show squiggles sooner.", "最后一次输入后等待此时长再检查。设短一些，波浪线会更快出现。", "마지막 입력 뒤 이 시간만큼 기다렸다가 검사합니다. 짧게 하면 물결선이 바로 나옵니다." },
            ["std::make_unique<T>(…) と std::make_shared<T>(…) を調べます。"] = new[] { "Checks std::make_unique<T>(…) and std::make_shared<T>(…).", "检查 std::make_unique<T>(…) 与 std::make_shared<T>(…)。", "std::make_unique<T>(…)와 std::make_shared<T>(…)를 검사합니다." },
            ["new T(…) を調べます(配置 new と new T[n] は調べません)。"] = new[] { "Checks new T(…) (placement new and new T[n] are not checked).", "检查 new T(…)（不检查 placement new 与 new T[n]）。", "new T(…)를 검사합니다(placement new와 new T[n]은 검사하지 않음)." },
            ["カンマ区切りのクラス名。誤って波線が出るクラスがあれば、ここに書くと出なくなります。"] = new[] { "Comma-separated class names. Add a class here if it gets false squiggles.", "逗号分隔的类名。若某个类出现误报的波浪线，写在这里即可不再显示。", "쉼표로 구분한 클래스 이름. 잘못 물결선이 나오는 클래스가 있으면 여기에 쓰면 나오지 않습니다." },
            ["True のとき、#include を足した、引数を写した、ファイル名を直した、などをステータスバーに 1 行出します。False でも、失敗の知らせは出ます。"] = new[] { "When True, shows one line in the status bar when an #include is added, parameters are copied, a file name is fixed, and so on. Failures are reported even when False.", "为 True 时，添加 #include、复制参数、修正文件名等时在状态栏显示一行提示。为 False 时也会提示失败。", "True이면 #include 추가, 매개변수 복사, 파일 이름 수정 등을 상태 표시줄에 1줄 표시합니다. False여도 실패 알림은 나옵니다." },
            ["True のとき、動作の記録を %LOCALAPPDATA%\\K-CppAssist\\vsix.log に書きます。不具合のとき、これを見ると原因が分かります。"] = new[] { "When True, writes an activity log to %LOCALAPPDATA%\\K-CppAssist\\vsix.log. When something goes wrong, the cause can be found there.", "为 True 时，将运行记录写入 %LOCALAPPDATA%\\K-CppAssist\\vsix.log。出现问题时，查看它即可找到原因。", "True이면 동작 기록을 %LOCALAPPDATA%\\K-CppAssist\\vsix.log에 씁니다. 문제가 생기면 이것을 보면 원인을 알 수 있습니다." },
            ["True のとき、std::vector → <vector> のような、組み込みの対応表で、ヘッダーを決めます。"] = new[] { "When True, decides the header from a built-in table such as std::vector → <vector>.", "为 True 时，用 std::vector → <vector> 这样的内置对应表决定头文件。", "True이면 std::vector → <vector> 같은 내장 대응표로 헤더를 정합니다." },
            ["True のとき、ソリューションの下のヘッダーから、class / struct / enum / using の定義を集めて、型の名前からヘッダーを決めます。"] = new[] { "When True, collects class / struct / enum / using definitions from headers under the solution and decides the header from the type name.", "为 True 时，从解决方案下的头文件收集 class / struct / enum / using 的定义，根据类型名决定头文件。", "True이면 솔루션 아래 헤더에서 class / struct / enum / using 정의를 모아 형식 이름으로 헤더를 정합니다." },
            ["「名前=ヘッダー」を、; か改行で区切って書きます。組み込みの表より先に使います。例: Vec3=\"math/vec3.h\";Json=<nlohmann/json.hpp>"] = new[] { "Write \"name=header\" entries separated by ; or new lines. Used before the built-in table. Example: Vec3=\"math/vec3.h\";Json=<nlohmann/json.hpp>", "以 ; 或换行分隔书写“名称=头文件”。优先于内置表使用。例：Vec3=\"math/vec3.h\";Json=<nlohmann/json.hpp>", "\"이름=헤더\"를 ; 나 줄바꿈으로 구분해 씁니다. 내장 표보다 먼저 씁니다. 예: Vec3=\"math/vec3.h\";Json=<nlohmann/json.hpp>" },
            ["False のとき、ヘッダーに自動で足すのは、標準・Windows・DirectX の表と、自分で決めた対応のものだけです(循環 include を避けるため)。True にすると、ソリューションの型も足します。"] = new[] { "When False, only entries from the standard / Windows / DirectX table and your custom mappings are added to headers automatically (to avoid circular includes). When True, solution types are added too.", "为 False 时，自动添加到头文件的只有标准 / Windows / DirectX 表和自定义对应（为避免循环 include）。为 True 时，解决方案的类型也会添加。", "False이면 헤더에 자동으로 추가하는 것은 표준·Windows·DirectX 표와 직접 정한 대응뿐입니다(순환 include를 피하기 위해). True로 하면 솔루션 형식도 추가합니다." },
            ["自動で足した直後に、その識別子を消したら、足した #include も戻します。その猶予の秒数です。0 で、戻さないようにします。"] = new[] { "If you delete the identifier right after an #include was added automatically, the #include is removed too. This is that grace period in seconds. 0 disables it.", "自动添加后若立即删除该标识符，也会撤销添加的 #include。这是其宽限秒数。为 0 则不撤销。", "자동으로 추가한 직후 그 식별자를 지우면 추가한 #include도 되돌립니다. 그 유예 초입니다. 0이면 되돌리지 않습니다." },
            ["True のとき、ソリューションの全ファイルの #include を、新しい名前に直します。"] = new[] { "When True, #include in all files of the solution is updated to the new name.", "为 True 时，将解决方案中所有文件的 #include 改为新名称。", "True이면 솔루션 전체 파일의 #include를 새 이름으로 고칩니다." },
            ["True のとき、Solution Explorer 以外(フォルダー ビュー、エクスプローラー、別のツール)での名前変更も見つけて、自動で直します。"] = new[] { "When True, renames made outside Solution Explorer (Folder View, Explorer, other tools) are also detected and fixed automatically.", "为 True 时，也检测在解决方案资源管理器以外（文件夹视图、资源管理器、其他工具）进行的重命名并自动修复。", "True이면 솔루션 탐색기 밖(폴더 보기, 탐색기, 다른 도구)에서의 이름 변경도 찾아 자동으로 고칩니다." },
            ["3 秒の間に、この件数より多くの名前変更が起きたら、git のブランチ切り替えなどの一括操作とみなして、自動では直しません。"] = new[] { "If more renames than this occur within 3 seconds, they are treated as a bulk operation such as a git branch switch and not fixed automatically.", "若 3 秒内发生的重命名多于此数，则视为 git 切换分支等批量操作，不自动修复。", "3초 동안 이 수보다 많은 이름 변경이 일어나면 git 브랜치 전환 같은 일괄 작업으로 보고 자동으로 고치지 않습니다." },
            ["True(既定)のとき、自動で直す前に、何を何に直すかを見せるダイアログを出します(相手・#include・CMake と、クラス名を直すかを、項目ごとに選べます)。False なら、確認せずに、ダイアログの初期値どおりに直します(相手・#include・CMake と、ファイル名と同じだったクラス名)。ダイアログの「次から確認しない」に印を付けて反映すると、False になります。"] = new[] { "True (default): before fixing automatically, shows a dialog with what will be changed (you can choose per item: paired file, #include, CMake and the class name). False: fixes without asking, using the dialog's defaults (paired file, #include, CMake, and the class name when it matched the file name). Checking \"Don't ask again\" in the dialog sets this to False.", "True（默认）：自动修复前显示对话框，列出将修改的内容（可逐项选择对应文件、#include、CMake 及是否修改类名）。False：不询问，按对话框的默认值修复（对应文件、#include、CMake，以及与文件名相同的类名）。在对话框中勾选“下次不再询问”并应用后会变为 False。", "True(기본): 자동으로 고치기 전에 무엇을 무엇으로 고칠지 보여 주는 대화 상자를 냅니다(짝 파일·#include·CMake와 클래스 이름을 항목마다 선택). False: 묻지 않고 대화 상자의 기본값대로 고칩니다(짝 파일·#include·CMake와 파일 이름과 같던 클래스 이름). 대화 상자의 \"다음부터 묻지 않기\"를 체크하고 반영하면 False가 됩니다." },
            ["エラーが複数あるとき、先頭に、一番上のエラーから直す案内を出します。"] = new[] { "When there are several errors, shows guidance at the top to fix the first error first.", "有多个错误时，在开头提示先从最上面的错误开始修复。", "오류가 여러 개일 때 맨 앞에 가장 위 오류부터 고치라는 안내를 냅니다." },
            ["True のとき、上のエラーの影響で出ていそうなエラーに、「連鎖の可能性」と書きます。"] = new[] { "When True, marks errors that are likely caused by an earlier error as \"possible cascade\".", "为 True 时，对可能由上方错误引起的错误标注“可能是连锁错误”。", "True이면 위 오류의 영향으로 나온 듯한 오류에 \"연쇄 가능성\"이라고 씁니다." },
            ["True のとき、主なエラーに、修正前と修正後のコードの例を出します。"] = new[] { "When True, shows before / after code examples for the main errors.", "为 True 时，为主要错误显示修改前后的代码示例。", "True이면 주요 오류에 수정 전·후 코드 예를 냅니다." },
            ["これを超えるエラーは、省略します(「原文」表示では、全部読めます)。"] = new[] { "Errors beyond this number are omitted (all can be read in the \"original\" view).", "超过此数的错误将被省略（在“原文”显示中可全部查看）。", "이 수를 넘는 오류는 생략합니다(\"원문\" 표시에서는 모두 볼 수 있음)." },
            ["False にすると、ビルドが終わってもエラーログを作りません(窓も自動では開きません)。"] = new[] { "When False, no error log is created after a build (and the window does not open automatically).", "为 False 时，构建结束后不生成错误日志（窗口也不会自动打开）。", "False로 하면 빌드가 끝나도 오류 로그를 만들지 않습니다(창도 자동으로 열리지 않음)." },
            ["True のとき、ビルドが終わってエラーがあれば、窓を前に出します(入力は奪いません)。False のときは、拡張機能 メニューから開きます。"] = new[] { "When True, brings the window to the front when a build ends with errors (it does not steal input). When False, open it from the Extensions menu.", "为 True 时，构建结束且有错误时将窗口置前（不会抢走输入）。为 False 时，从“扩展”菜单打开。", "True이면 빌드가 끝나고 오류가 있으면 창을 앞으로 냅니다(입력은 빼앗지 않음). False이면 확장 메뉴에서 엽니다." },
            ["True のとき、未解決の外部シンボル(LNK2019 など)について、ソリューションの .lib とソースを探して、原因を言い当てます。時間がかかるときは False にしてください。"] = new[] { "When True, searches the solution's .lib files and sources for unresolved external symbols (LNK2019 etc.) to pinpoint the cause. Set False if it takes too long.", "为 True 时，针对未解析的外部符号（LNK2019 等）搜索解决方案的 .lib 与源文件，找出原因。耗时较长时请设为 False。", "True이면 확인되지 않은 외부 기호(LNK2019 등)에 대해 솔루션의 .lib와 소스를 찾아 원인을 짚어 냅니다. 시간이 걸리면 False로 하세요." },
            ["原因を探す処理の、1 回あたりの時間の上限です。"] = new[] { "Upper limit of time per search for causes.", "查找原因时每次的时间上限。", "원인을 찾는 처리 1회당 시간 상한입니다." },
            ["原因を探すとき、読む .lib の数の上限です。"] = new[] { "Upper limit of .lib files read when searching for causes.", "查找原因时读取的 .lib 数量上限。", "원인을 찾을 때 읽을 .lib 수의 상한입니다." },
            ["True のとき、std::basic_string<char, …> を std::string のように、読みやすい形にします。"] = new[] { "When True, makes type names readable, e.g. std::basic_string<char, …> becomes std::string.", "为 True 时，将 std::basic_string<char, …> 等改写为 std::string 这样易读的形式。", "True이면 std::basic_string<char, …>를 std::string처럼 읽기 쉬운 형태로 바꿉니다." },
            ["True のとき、エラー コードごとの見出しの下に、対処のヒントを出します。"] = new[] { "When True, shows hints for fixing below each error-code heading.", "为 True 时，在每个错误代码的标题下显示处理提示。", "True이면 오류 코드별 제목 아래에 대처 힌트를 냅니다." },
            ["窓を開いたときの、「警告も表示」の初期値です。"] = new[] { "Initial value of \"Show warnings too\" when the window opens.", "打开窗口时“也显示警告”的初始值。", "창을 열었을 때 \"경고도 표시\"의 초기값입니다." },
            ["窓を開いたときの、「経路を全部表示」の初期値です。"] = new[] { "Initial value of \"Show the full path\" when the window opens.", "打开窗口时“显示完整路径”的初始值。", "창을 열었을 때 \"경로 전체 표시\"의 초기값입니다." },
            ["窓を開いたときの、「原文を併記」の初期値です。"] = new[] { "Initial value of \"Show the original message too\" when the window opens.", "打开窗口时“同时显示原文”的初始值。", "창을 열었을 때 \"원문 함께 표시\"의 초기값입니다." },
            ["窓を開いたときの、「原文」(整理せずに色だけ付ける)の初期値です。"] = new[] { "Initial value of \"Original message\" (colored only, not reorganized) when the window opens.", "打开窗口时“原文”（不整理，仅着色）的初始值。", "창을 열었을 때 \"원문\"(정리하지 않고 색만 입힘)의 초기값입니다." },
            ["false(既定): 使っていない #include の削除は、cpp だけ。true: ヘッダーも対象にする(他のファイルが、そのヘッダー経由で include を受け取っていると、ビルドが通らなくなることがあります)。"] = new[] { "false (default): removing unused #include applies to cpp files only. true: headers too (builds may break if other files get includes through that header).", "false（默认）：删除未使用的 #include 仅针对 cpp。true：头文件也作为对象（若其他文件经由该头文件获得 include，可能导致无法构建）。", "false(기본): 사용하지 않는 #include 삭제는 cpp만. true: 헤더도 대상(다른 파일이 그 헤더를 통해 include를 받고 있으면 빌드가 안 될 수 있음)." },
            ["true: Ctrl+. の電球に、宣言・定義の相手を作る、引数を合わせる、変数に型を付ける、を出す。"] = new[] { "true: shows create counterpart declaration / definition, sync parameters and add type to variable in the Ctrl+. light bulb.", "true：在 Ctrl+. 灯泡中显示生成对应声明 / 定义、同步参数、为变量添加类型。", "true: Ctrl+. 전구에 선언·정의의 짝 만들기, 매개변수 맞추기, 변수에 형식 붙이기를 표시." },
            ["True のとき、クラスの電球に「JSON に読み書きできるようにする (nlohmann)」を出します。初期値は False(nlohmann を使わないプロジェクトでは邪魔になるため)。"] = new[] { "When True, shows \"Make JSON serializable (nlohmann)\" in the class light bulb. Default False (it gets in the way in projects that do not use nlohmann).", "为 True 时，在类的灯泡中显示“使其可读写 JSON (nlohmann)”。默认 False（不使用 nlohmann 的项目会觉得碍事）。", "True이면 클래스 전구에 \"JSON 읽기·쓰기 가능하게 (nlohmann)\"를 표시합니다. 기본값 False(nlohmann을 쓰지 않는 프로젝트에서는 방해가 되므로)." },
            ["True のとき、クラスの電球に「cereal で保存できるようにする (serialize)」を出します。初期値は False。"] = new[] { "When True, shows \"Make serializable with cereal (serialize)\" in the class light bulb. Default False.", "为 True 时，在类的灯泡中显示“使其可用 cereal 保存 (serialize)”。默认 False。", "True이면 클래스 전구에 \"cereal로 저장 가능하게 (serialize)\"를 표시합니다. 기본값 False." },
            ["True のとき、クラスの電球に「デバッガーの表示 (Natvis) を作る」を出します。初期値は False。"] = new[] { "When True, shows \"Generate debugger display (Natvis)\" in the class light bulb. Default False.", "为 True 时，在类的灯泡中显示“生成调试器显示 (Natvis)”。默认 False。", "True이면 클래스 전구에 \"디버거 표시 (Natvis) 만들기\"를 표시합니다. 기본값 False." },
            ["True のとき、enum / enum class の値を switch (値) { で受けて改行すると、本体が空なら、値ごとの「case 値: break;」と「default: break;」を自動で入れます。enum の型が決められない switch(整数など)では、何もしません。Ctrl+Z 1 回で消えます。"] = new[] { "When True, typing switch (value) { on an enum / enum class value and pressing Enter inserts \"case value: break;\" for each value and \"default: break;\" if the body is empty. Does nothing for switches whose enum type cannot be determined (integers etc.). One Ctrl+Z removes it.", "为 True 时，对 enum / enum class 的值写 switch (值) { 并换行后，若主体为空，自动插入每个值的“case 值: break;”和“default: break;”。无法确定 enum 类型的 switch（整数等）不做处理。按一次 Ctrl+Z 即可撤销。", "True이면 enum / enum class 값을 switch (값) { 으로 받고 줄을 바꾸면 본문이 비어 있을 때 값마다 \"case 값: break;\"와 \"default: break;\"를 자동으로 넣습니다. enum 형식을 정할 수 없는 switch(정수 등)에서는 아무것도 하지 않습니다. Ctrl+Z 1번으로 사라집니다." },
            ["True のとき、プロジェクトに新しく足した空のヘッダーに #pragma once・namespace・class を、空の cpp に #include と namespace を書きます(作ってから 2 分以内の、空のファイルだけ)。"] = new[] { "When True, writes #pragma once / namespace / class into new empty headers added to the project, and #include / namespace into new empty cpp files (only empty files created within the last 2 minutes).", "为 True 时，向项目新加入的空头文件写入 #pragma once、namespace、class，向空 cpp 写入 #include 与 namespace（仅限创建后 2 分钟内的空文件）。", "True이면 프로젝트에 새로 추가한 빈 헤더에 #pragma once·namespace·class를, 빈 cpp에 #include와 namespace를 씁니다(만든 지 2분 이내의 빈 파일만)." },
            ["True のとき、ヘッダーに「class クラス名 {」から「};」までを書きます。False なら、namespace だけ。"] = new[] { "When True, writes from \"class ClassName {\" to \"};\" in the header. When False, only the namespace.", "为 True 时，在头文件中写入从“class 类名 {”到“};”。为 False 时只写 namespace。", "True이면 헤더에 \"class 클래스명 {\"부터 \"};\"까지 씁니다. False이면 namespace만." },
            ["True(初期値)のとき、新しいヘッダーのひな形と、VS の「クラスの追加」で作ったクラスの public: に、「Foo() = default;」と「~Foo() = default;」を書きます。VS がすでにコンストラクター・デストラクターを書いていれば、そちらを残します。"] = new[] { "True (default): writes \"Foo() = default;\" and \"~Foo() = default;\" under public: in new header templates and in classes made with VS \"Add Class\". If VS already wrote a constructor / destructor, those are kept.", "True（默认）：在新头文件模板以及用 VS“添加类”创建的类的 public: 中写入“Foo() = default;”和“~Foo() = default;”。若 VS 已写构造 / 析构函数，则保留其内容。", "True(기본): 새 헤더 템플릿과 VS의 \"클래스 추가\"로 만든 클래스의 public:에 \"Foo() = default;\"와 \"~Foo() = default;\"를 씁니다. VS가 이미 생성자·소멸자를 썼다면 그것을 남깁니다." },
            ["SameAsFile: ファイル名と同じ(初期値)。PascalCase: game_object → GameObject。SnakeCase: GameObject → game_object。CamelCase: game_object → gameObject。"] = new[] { "SameAsFile: same as the file name (default). PascalCase: game_object → GameObject. SnakeCase: GameObject → game_object. CamelCase: game_object → gameObject.", "SameAsFile：与文件名相同（默认）。PascalCase：game_object → GameObject。SnakeCase：GameObject → game_object。CamelCase：game_object → gameObject。", "SameAsFile: 파일 이름과 같음(기본). PascalCase: game_object → GameObject. SnakeCase: GameObject → game_object. CamelCase: game_object → gameObject." },
            ["Auto: ソリューションの既存のヘッダーで、行頭の namespace が一番多いもの(初期値)。Fixed: 下の名前を使う。None: 書かない。"] = new[] { "Auto: the most common top-level namespace in existing solution headers (default). Fixed: use the name below. None: do not write one.", "Auto：解决方案现有头文件中行首最常见的 namespace（默认）。Fixed：使用下面的名称。None：不写。", "Auto: 솔루션의 기존 헤더에서 줄 맨 앞 namespace가 가장 많은 것(기본). Fixed: 아래 이름 사용. None: 쓰지 않음." },
            ["namespace の決めかたが Fixed のときに使う名前。「Game::Core」のように :: でつなげます。"] = new[] { "Name used when namespace selection is Fixed. Join with :: such as \"Game::Core\".", "namespace 决定方式为 Fixed 时使用的名称。像“Game::Core”这样用 :: 连接。", "namespace 정하는 방식이 Fixed일 때 쓰는 이름. \"Game::Core\"처럼 ::로 잇습니다." },
            ["Auto: 既存のヘッダーで多いほう(タブか、空白 2 / 4)。判断できなければタブ。"] = new[] { "Auto: whichever is more common in existing headers (tabs or 2 / 4 spaces). Tabs if undecidable.", "Auto：现有头文件中较多的一种（制表符，或 2 / 4 个空格）。无法判断时用制表符。", "Auto: 기존 헤더에서 많은 쪽(탭, 또는 공백 2 / 4). 판단할 수 없으면 탭." },
            ["True(初期値)のとき、namespace の中の class を 1 段字下げします。"] = new[] { "True (default): indents the class inside the namespace by one level.", "True（默认）：将 namespace 中的 class 缩进一级。", "True(기본): namespace 안의 class를 한 단계 들여씁니다." },
            ["PragmaOnce: #pragma once(初期値)。IncludeGuard: #ifndef / #define / #endif。"] = new[] { "PragmaOnce: #pragma once (default). IncludeGuard: #ifndef / #define / #endif.", "PragmaOnce：#pragma once（默认）。IncludeGuard：#ifndef / #define / #endif。", "PragmaOnce: #pragma once(기본). IncludeGuard: #ifndef / #define / #endif." },
            ["True のとき、「}  // namespace 名前」と書きます。False(初期値)なら「}」だけです。"] = new[] { "When True, writes \"}  // namespace name\". When False (default), only \"}\".", "为 True 时写“}  // namespace 名称”。为 False（默认）时只写“}”。", "True이면 \"}  // namespace 이름\"이라고 씁니다. False(기본)이면 \"}\"만." },
            ["True(初期値)のとき、プロジェクトの「強制インクルード ファイル」(/FI、ForcedIncludeFiles)に pch.h などがあれば、VS の「クラスの追加」が cpp に書いた #include \"pch.h\" を、書き直すときに消します。/FI で毎回読み込まれるので、書かなくてもビルドできます。"] = new[] { "True (default): if the project's \"Forced Include File\" (/FI, ForcedIncludeFiles) contains pch.h or similar, the #include \"pch.h\" written by VS \"Add Class\" into the cpp is removed when rewriting. Since /FI includes it every time, it builds without it.", "True（默认）：若项目的“强制包含文件”（/FI、ForcedIncludeFiles）中有 pch.h 等，重写时删除 VS“添加类”在 cpp 中写入的 #include \"pch.h\"。由于 /FI 每次都会包含，不写也能构建。", "True(기본): 프로젝트의 \"강제 포함 파일\"(/FI, ForcedIncludeFiles)에 pch.h 등이 있으면 VS의 \"클래스 추가\"가 cpp에 쓴 #include \"pch.h\"를 다시 쓸 때 지웁니다. /FI로 매번 읽으므로 쓰지 않아도 빌드됩니다." },
